// Generates src/defaults.js from rules/rules.json.
// Run after every edit of rules.json:  node tools/build-defaults.mjs
// Content scripts need the rules synchronously at document_start, before
// chrome.storage (async) can answer, so the bundled rules are baked in here.
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const rules = JSON.parse(readFileSync(join(root, "rules/rules.json"), "utf8"));

const out =
  "// AUTO-GENERATED by tools/build-defaults.mjs from rules/rules.json. Do not edit.\n" +
  "globalThis.QQ_DEFAULT_RULES = " + JSON.stringify(rules) + ";\n";

writeFileSync(join(root, "src/defaults.js"), out);
console.log("src/defaults.js written, rules version", rules.version);
